mapper.select:
SELECT id, tenant_id, owner_module, entity_type, revision_no, source_form_revision_id, fields_json,
    creator, updater, create_time, update_time, deleted
FROM plt_entity_extension_definition
WHERE deleted = b'0' AND tenant_id = #{query.tenantId} AND owner_module = #{query.ownerModule}
  AND entity_type = #{query.entityType} AND source_form_revision_id = #{query.sourceFormRevisionId}

mapper.update:
UPDATE plt_entity_extension_value SET definition_revision_id = #{row.definitionRevisionId}, values_json = #{row.valuesJson},
    version = version + 1, updater = #{row.updater}, update_time = CURRENT_TIMESTAMP(3)
WHERE deleted = b'0' AND id = #{row.id} AND tenant_id = #{row.tenantId} AND version = #{row.version}

mapper.delete:
DELETE FROM plt_entity_extension_value
WHERE id = #{row.id} AND tenant_id = #{row.tenantId} AND version = #{row.version}
    AND revision_id = #{row.revisionId}

mapper.update:
UPDATE plt_entity_form_binding SET form_revision_id = #{row.formRevisionId}, extension_definition_revision_id = #{row.extensionDefinitionRevisionId}, field_bindings_json = #{row.fieldBindingsJson},
    version = version + 1, updater = #{row.updater}, update_time = CURRENT_TIMESTAMP(3)
WHERE deleted = b'0' AND id = #{row.id} AND tenant_id = #{row.tenantId} AND version = #{row.version}

mapper.delete:
DELETE FROM plt_entity_form_binding
WHERE id = #{row.id} AND tenant_id = #{row.tenantId} AND version = #{row.version}
    AND revision_id = #{row.revisionId}
